const raw = $input.first().json;
const body = raw.body ?? raw;

const code = body.code;
const wabaId = body.waba_id || null;
const phoneNumberId = body.phone_number_id || null;
const businessId = body.business_id || null;
const conexaoId = body.conexaoId || body.conexao_id || null;
const contaId = body.contaId || body.conta_id || null;
const nome = body.NomeConexao || body.nome || 'WhatsApp API Oficial';

if (!code || typeof code !== 'string') {
  throw new Error('Campo code obrigatorio.');
}

if (!conexaoId && !contaId) {
  throw new Error('Informe conexaoId (atualizar) ou contaId (criar nova conexao).');
}

return [
  {
    json: {
      code,
      waba_id: wabaId,
      phone_number_id: phoneNumberId,
      business_id: businessId,
      conexaoId,
      contaId,
      NomeConexao: nome
    }
  }
];

const config = $('CONFIG API OFICIAL').first().json;
if (!config?.app_id || !config?.app_secret) {
  throw new Error('Config API Oficial incompleta em SAAS_Config_ApiOficial.');
}

const curto = $('TROCAR CODE POR TOKEN CURTO').first().json;
const longo = $('TROCAR POR TOKEN LONGO').first().json;

if (curto.error) {
  throw new Error(curto.error.message || 'Falha ao trocar code por token curto.');
}
if (!curto.access_token) {
  throw new Error('Resposta da Meta sem access_token (curto).');
}
if (longo.error) {
  throw new Error(longo.error.message || 'Falha ao trocar por token longo.');
}
if (!longo.access_token) {
  throw new Error('Resposta da Meta sem access_token (longo).');
}

return [{ json: longo }];

const entrada = $('VALIDAR ENTRADA').first().json;
const token = $('TROCAR POR TOKEN LONGO').first().json.access_token;

let wabaId = entrada.waba_id;
if (!wabaId) {
  wabaId = $('BUSCAR WABA').first().json.data?.[0]?.id;
}
if (!wabaId) {
  throw new Error('waba_id nao encontrado.');
}

const res = await this.helpers.httpRequest({
  method: 'POST',
  url: `https://graph.facebook.com/v25.0/${wabaId}/subscribed_apps`,
  headers: {
    Authorization: `Bearer ${token}`,
    'Content-Type': 'application/json'
  },
  body: {},
  json: true
});

return [{ json: res }];

const entrada = $('VALIDAR ENTRADA').first().json;
const token = $('TROCAR POR TOKEN LONGO').first().json.access_token;

let phone_number_id = entrada.phone_number_id || null;
if (!phone_number_id) {
  phone_number_id = $('BUSCAR PHONE').first().json.data?.[0]?.id || null;
}
if (!phone_number_id) {
  throw new Error('phone_number_id nao encontrado para registro.');
}

const headers = {
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json'
};

const phoneRes = await this.helpers.httpRequest({
  method: 'GET',
  url: `https://graph.facebook.com/v25.0/${phone_number_id}`,
  qs: { fields: 'status' },
  headers,
  json: true
});

if (phoneRes.error) {
  throw new Error(phoneRes.error.message || 'Falha ao consultar status do numero.');
}

const statusAntes = phoneRes.status || null;
let pin = null;
let registrado = false;
let statusDepois = statusAntes;

if (statusAntes !== 'CONNECTED') {
  pin = String(Math.floor(100000 + Math.random() * 900000));

  const regRes = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://graph.facebook.com/v25.0/${phone_number_id}/register`,
    headers,
    body: {
      messaging_product: 'whatsapp',
      pin
    },
    json: true
  });

  if (regRes.error) {
    const code = regRes.error.code;
    const msg = regRes.error.message || regRes.error.error_user_msg || 'Falha ao registrar numero na Meta.';
    if (code === 133005) {
      throw new Error('PIN de verificacao em duas etapas incorreto. O numero ja possui 2FA; informe o PIN existente.');
    }
    throw new Error(msg);
  }

  registrado = true;
  statusDepois = 'CONNECTED';
}

return [
  {
    json: {
      phone_number_id,
      pin,
      registrado,
      status_antes: statusAntes,
      status_depois: statusDepois
    }
  }
];

const entrada = $('VALIDAR ENTRADA').first().json;
const tokenLongo = $('TROCAR POR TOKEN LONGO').first().json;
const access_token = tokenLongo.access_token;
const expires_in = tokenLongo.expires_in || null;
const registro = $('REGISTRAR NUMERO').first().json;

let business_id = entrada.business_id || null;
let waba_id = entrada.waba_id || null;
let phone_number_id = entrada.phone_number_id || null;
let Telefone = null;
let verified_name = null;

const temIdsFront = !!waba_id && !!phone_number_id;

if (temIdsFront) {
  const phoneRes = $('BUSCAR DETALHES PHONE').first().json;
  if (phoneRes.error) {
    throw new Error(phoneRes.error.message || 'Falha ao buscar detalhes do numero.');
  }
  Telefone = phoneRes.display_phone_number
    ? String(phoneRes.display_phone_number).replace(/\D/g, '')
    : null;
  verified_name = phoneRes.verified_name || null;
  if (!Telefone) {
    throw new Error('Meta nao retornou display_phone_number para o phone_number_id.');
  }
} else {
  const businessRes = $('BUSCAR BUSINESS').first().json;
  if (businessRes.error) {
    throw new Error(businessRes.error.message || 'Falha ao buscar businesses.');
  }
  business_id = businessRes.data?.[0]?.id || null;
  if (!business_id) {
    throw new Error('Nenhuma conta Business encontrada.');
  }

  const wabaRes = $('BUSCAR WABA').first().json;
  if (wabaRes.error) {
    throw new Error(wabaRes.error.message || 'Falha ao buscar WABA.');
  }
  waba_id = wabaRes.data?.[0]?.id || null;
  if (!waba_id) {
    throw new Error('Nenhuma WABA encontrada.');
  }

  const phoneRes = $('BUSCAR PHONE').first().json;
  if (phoneRes.error) {
    throw new Error(phoneRes.error.message || 'Falha ao buscar phone_numbers.');
  }
  const phone = phoneRes.data?.[0];
  if (!phone?.id) {
    throw new Error('Nenhum phone_number_id encontrado.');
  }
  phone_number_id = phone.id;
  Telefone = phone.display_phone_number
    ? String(phone.display_phone_number).replace(/\D/g, '')
    : null;
  verified_name = phone.verified_name || null;
  if (!Telefone) {
    throw new Error('Meta nao retornou display_phone_number.');
  }
}

const inscricao = $('INSCREVER WABA').first().json;
if (inscricao.error) {
  throw new Error(inscricao.error.message || 'Falha ao inscrever app na WABA.');
}
if (inscricao.success !== true) {
  throw new Error('subscribed_apps nao retornou success:true.');
}

const expiresAt = expires_in
  ? new Date(Date.now() + Number(expires_in) * 1000).toISOString()
  : null;

const nomeConexao =
  entrada.NomeConexao && entrada.NomeConexao !== 'WhatsApp API Oficial'
    ? entrada.NomeConexao
    : verified_name || entrada.NomeConexao;

const payload = {
  ok: true,
  access_token,
  expires_in,
  expires_at: expiresAt,
  business_id,
  waba_id,
  phone_number_id,
  Telefone,
  conexaoId: entrada.conexaoId,
  contaId: entrada.contaId,
  NomeConexao: nomeConexao,
  connected_at: new Date().toISOString(),
  numero_registrado: registro.registrado,
  metaPhoneStatus: registro.status_depois || null
};

if (registro.pin) {
  payload.metaPinVerificacao = registro.pin;
}

return [{ json: payload }];

const row = $input.first().json;
const payload = $('MONTAR PAYLOAD FINAL').first().json;

if (!row?.id) {
  throw new Error('Falha ao salvar conexao em SAAS_Conexoes.');
}

const resposta = {
  ok: true,
  conexaoId: row.id,
  contaId: row.contaId,
  NomeConexao: row.NomeConexao,
  business_id: row.business_id,
  waba_id: row.waba_id,
  phone_number_id: row.phone_number_id,
  Telefone: row.Telefone,
  expires_in: row.expires_in,
  apiOficial: row.apiOficial,
  metaPhoneStatus: row.metaPhoneStatus || payload.metaPhoneStatus || null,
  numero_registrado: payload.numero_registrado === true
};

if (payload.metaPinVerificacao) {
  resposta.metaPinVerificacao = payload.metaPinVerificacao;
  resposta.aviso_pin = 'Guarde este PIN de 6 digitos. Ele e a verificacao em duas etapas do numero na Meta.';
}

return [{ json: resposta }];
